#!/usr/bin/env python3
from __future__ import annotations

import inspect
import platform
import sys
import types
from pathlib import Path


def _run_impl(source: str, impl_name: str) -> int:
    module_name = f'{__name__}.{impl_name}'
    module = types.ModuleType(module_name)
    module.__file__ = str(Path(__file__).resolve())
    sys.modules[module_name] = module
    namespace = module.__dict__
    exec(compile(source, str(Path(__file__).resolve()), 'exec'), namespace, namespace)
    main_fn = namespace.get('main')
    if not callable(main_fn):
        raise RuntimeError(f"Selected implementation '{impl_name}' for 'ovir_downloader' does not define main()")
    sig = inspect.signature(main_fn)
    if len(sig.parameters) == 0:
        return int(main_fn())
    if len(sig.parameters) == 1:
        return int(main_fn(sys.argv))
    raise RuntimeError(f"Selected implementation '{impl_name}' for 'ovir_downloader' has unsupported main() signature")


def main() -> int:
    if platform.system().strip().lower().startswith('win'):
        return _run_impl(_WINDOWS_IMPL, 'windows')
    return _run_impl(_LINUX_IMPL, 'linux')


_LINUX_IMPL = 'from __future__ import annotations\n\nimport os\nimport re\nimport shutil\nimport subprocess\nimport tempfile\nfrom pathlib import Path\n\nfrom _linux_common import CONFIG_FILE, PROJECT_ROOT, apply_optional_proxy, load_config, resolve_path, shell_exists\n\n\ndef _is_true(v: object) -> bool:\n\treturn str(v).strip().lower() in {"1", "true", "yes"}\n\n\ndef _venv_python(build_dir: Path) -> Path:\n\treturn build_dir / "openvino.genai" / "tools" / "llm_bench" / "python-env" / "bin" / "python"\n\n\ndef _run_capture(cmd: list[str], env: dict[str, str], cwd: Path) -> tuple[int, str]:\n\tp = subprocess.run(cmd, cwd=str(cwd), env=env, capture_output=True, text=True)\n\tout = (p.stdout or "") + (p.stderr or "")\n\tif out:\n\t\tprint(out, end="" if out.endswith("\\n") else "\\n")\n\treturn p.returncode, out\n\n\ndef _get_transformers_version(py: Path, env: dict[str, str], cwd: Path) -> str:\n\tcode = "import transformers; print(transformers.__version__)"\n\tp = subprocess.run([str(py), "-c", code], cwd=str(cwd), env=env, capture_output=True, text=True)\n\treturn (p.stdout or "").strip() if p.returncode == 0 else ""\n\n\ndef _install_transformers(py: Path, env: dict[str, str], cwd: Path, version: str) -> bool:\n\tif not version:\n\t\treturn False\n\tcmd = [str(py), "-m", "pip", "install", "-q", f"transformers=={version}"]\n\treturn subprocess.run(cmd, cwd=str(cwd), env=env).returncode == 0\n\n\ndef _restore_transformers(py: Path, env: dict[str, str], cwd: Path, initial_tf: str) -> None:\n\tif initial_tf:\n\t\tprint(f"Info: Restoring transformers=={initial_tf}")\n\t\t_install_transformers(py, env, cwd, initial_tf)\n\telse:\n\t\tprint("Info: Restoring environment by removing transformers")\n\t\tsubprocess.run([str(py), "-m", "pip", "uninstall", "-y", "transformers"], cwd=str(cwd), env=env, capture_output=True, text=True)\n\n\ndef _extract_failure_reason(output: str) -> str:\n\tpats = [\n\t\tr"Maximum required is.*",\n\t\tr"not supported.*",\n\t\tr"unsupported.*",\n\t\tr"Unknown model type.*",\n\t\tr"requires\\s+transformers.*",\n\t\tr"ValueError.*",\n\t\tr"RuntimeError.*",\n\t\tr"OSError.*",\n\t\tr"Exception.*",\n\t\tr"Traceback.*",\n\t]\n\tlines = [ln.strip() for ln in output.splitlines() if ln.strip()]\n\tfor pat in pats:\n\t\thits = [ln for ln in lines if re.search(pat, ln, flags=re.IGNORECASE)]\n\t\tif hits:\n\t\t\treturn hits[-1]\n\treturn lines[-1] if lines else "Unknown export failure (empty log output)"\n\n\ndef _extract_target_tf(output: str) -> str:\n\tm = re.search(r"Maximum required is\\s+([0-9]+\\.[0-9]+\\.[0-9]+)", output)\n\tif m:\n\t\treturn m.group(1)\n\tm = re.search(r"requires\\s+transformers[^0-9]*([0-9]+\\.[0-9]+\\.[0-9]+)", output, flags=re.IGNORECASE)\n\tif m:\n\t\treturn m.group(1)\n\tm = re.search(r"transformers==([0-9]+\\.[0-9]+\\.[0-9]+)", output)\n\treturn m.group(1) if m else ""\n\n\ndef _optimum_cmd(py: Path, model: str, out_dir: Path, params: dict[str, object]) -> list[str]:\n\tcmd = [str(py), "-m", "optimum.commands.optimum_cli", "export", "openvino", "-m", model]\n\n\tweight_format = str(params.get("weight_format") or "").strip()\n\tif weight_format:\n\t\tcmd += ["--weight-format", weight_format]\n\n\tif _is_true(params.get("sym", False)):\n\t\tcmd += ["--sym"]\n\n\tratio = str(params.get("ratio") or "").strip()\n\tif ratio:\n\t\tcmd += ["--ratio", ratio]\n\n\tgroup_size = str(params.get("group_size") or "").strip()\n\tif group_size:\n\t\tcmd += ["--group-size", group_size]\n\n\tif _is_true(params.get("trust_remote_code", False)):\n\t\tcmd += ["--trust-remote-code"]\n\n\tcmd += [str(out_dir)]\n\treturn cmd\n\n\ndef _export_with_retry(\n\tpy: Path,\n\tmodel: str,\n\tdevice: str,\n\thf_root: Path,\n\tparams: dict[str, object],\n\tenv: dict[str, str],\n\tcwd: Path,\n\tinitial_tf: str,\n) -> tuple[Path | None, str | None]:\n\ttmp = Path(tempfile.mkdtemp(prefix=f".{device.lower()}_", dir=str(hf_root)))\n\trc, out = _run_capture(_optimum_cmd(py, model, tmp, params), env, cwd)\n\tif rc == 0:\n\t\treturn tmp, None\n\n\ttarget_tf = _extract_target_tf(out)\n\tchanged_tf = False\n\tcombined = out\n\n\tif target_tf:\n\t\tprint(f"Info: {device} export for {model} suggests transformers=={target_tf}. Retrying with that version")\n\t\tcurrent = _get_transformers_version(py, env, cwd)\n\t\tchanged_tf = current != target_tf\n\t\tif _install_transformers(py, env, cwd, target_tf):\n\t\t\tshutil.rmtree(tmp, ignore_errors=True)\n\t\t\ttmp = Path(tempfile.mkdtemp(prefix=f".{device.lower()}_retry_", dir=str(hf_root)))\n\t\t\trc2, out2 = _run_capture(_optimum_cmd(py, model, tmp, params), env, cwd)\n\t\t\tif rc2 == 0:\n\t\t\t\tif changed_tf:\n\t\t\t\t\t_restore_transformers(py, env, cwd, initial_tf)\n\t\t\t\treturn tmp, None\n\t\t\tcombined = (combined + "\\n" + out2).strip()\n\n\tif changed_tf:\n\t\t_restore_transformers(py, env, cwd, initial_tf)\n\n\treason = _extract_failure_reason(combined)\n\tshutil.rmtree(tmp, ignore_errors=True)\n\treturn None, reason\n\n\ndef main() -> int:\n\tif not CONFIG_FILE.is_file():\n\t\tprint(f"Error: {CONFIG_FILE} not found.")\n\t\treturn 1\n\tif not shell_exists("python3"):\n\t\tprint("Error: python3 not found.")\n\t\treturn 1\n\n\tcfg = load_config()\n\tenv = dict(os.environ)\n\tapply_optional_proxy(cfg, env)\n\n\tir_cfg = cfg.get("ir_models") or {}\n\thf_token = str(ir_cfg.get("hf_token") or "").strip()\n\tif hf_token:\n\t\tenv["HF_TOKEN"] = hf_token\n\t\tenv["HUGGINGFACE_HUB_TOKEN"] = hf_token\n\t\tenv["HF_HUB_TOKEN"] = hf_token\n\t\tprint(f"Applied optional hf_token from {CONFIG_FILE}")\n\n\tbuild_dir_raw = cfg.get("build_dir")\n\tir_dir_raw = cfg.get("ir_dir")\n\tif not build_dir_raw:\n\t\tprint(f"Error: Missing build_dir in {CONFIG_FILE}")\n\t\treturn 1\n\tif not ir_dir_raw:\n\t\tprint(f"Error: Missing ir_dir in {CONFIG_FILE}")\n\t\treturn 1\n\n\tbuild_dir = resolve_path(str(build_dir_raw))\n\thf_root = resolve_path(str(ir_dir_raw))\n\thf_root.mkdir(parents=True, exist_ok=True)\n\tprint(f"IR models root set to: {hf_root}")\n\n\tpy = _venv_python(build_dir)\n\tif not py.is_file():\n\t\tprint("Error: GenAI Python environment missing. Run SCRIPTS/genai_build.py first.")\n\t\treturn 1\n\n\tchk = subprocess.run([str(py), "-m", "optimum.commands.optimum_cli", "--help"], capture_output=True, text=True, env=env)\n\tif chk.returncode != 0:\n\t\tprint("Error: optimum-cli not found in GenAI environment")\n\t\treturn 1\n\n\tmodels = [str(m).strip() for m in (ir_cfg.get("models") or []) if str(m).strip()]\n\tif not models:\n\t\tprint("Error: No models found in ir_models.models")\n\t\treturn 1\n\n\tparams = ir_cfg.get("params") or {}\n\tgpu_params = params.get("gpu") or {}\n\tnpu_params = params.get("npu") or {}\n\n\tinitial_tf = _get_transformers_version(py, env, PROJECT_ROOT)\n\tif initial_tf:\n\t\tprint(f"Detected transformers version: {initial_tf}")\n\telse:\n\t\tprint("Warning: transformers is not currently installed in the active environment.")\n\n\tsuccess_count = 0\n\tfail_count = 0\n\tfailures: list[str] = []\n\tstatuses: list[str] = []\n\n\tfor model in models:\n\t\tprint("\\n============================================================")\n\t\tprint(f"Model: {model}")\n\t\tprint("============================================================")\n\n\t\tstripped = model.split("/", 1)[-1]\n\t\tsafe = stripped.replace("/", "__")\n\n\t\tfor device, pset in (("NPU", npu_params), ("GPU", gpu_params)):\n\t\t\tout_dir = hf_root / device / safe\n\t\t\tif (out_dir / "openvino_model.xml").is_file():\n\t\t\t\tprint(f"Skipping {device} export for {model} (already exists at {out_dir})")\n\t\t\t\tsuccess_count += 1\n\t\t\t\tstatuses.append(f"{device}|{model}|QUANTIZED")\n\t\t\t\tcontinue\n\n\t\t\tprint(f"Exporting {device} model: {model} -> {out_dir}")\n\t\t\ttmp, reason = _export_with_retry(py, model, device, hf_root, pset, env, PROJECT_ROOT, initial_tf)\n\t\t\tif tmp and tmp.is_dir():\n\t\t\t\tout_dir.parent.mkdir(parents=True, exist_ok=True)\n\t\t\t\tshutil.rmtree(out_dir, ignore_errors=True)\n\t\t\t\tshutil.move(str(tmp), str(out_dir))\n\t\t\t\tsuccess_count += 1\n\t\t\t\tstatuses.append(f"{device}|{model}|QUANTIZED")\n\t\t\telse:\n\t\t\t\tfail_count += 1\n\t\t\t\tmsg = reason or "Unknown export failure"\n\t\t\t\tprint(f"Warning: {device} export failed for {model}")\n\t\t\t\tprint(f"Reason: {msg}")\n\t\t\t\tfailures.append(f"{device}|{model}|{msg}")\n\t\t\t\tstatuses.append(f"{device}|{model}|NOT_QUANTIZED")\n\n\tprint("\\nDevice-wise quantization status:")\n\tif statuses:\n\t\tfor item in statuses:\n\t\t\td, m, s = item.split("|", 2)\n\t\t\tprint(f"  - {d} :: {m} :: {s}")\n\telse:\n\t\tprint("  - NONE")\n\n\tprint("\\nSummary:")\n\tprint(f"  - successful_exports: {success_count}")\n\tprint(f"  - failed_exports: {fail_count}")\n\tif failures:\n\t\tprint("\\nFailures:")\n\t\tfor item in failures:\n\t\t\td, m, r = item.split("|", 2)\n\t\t\tprint(f"  - {d} :: {m} :: {r}")\n\n\tprint("Process complete.")\n\treturn 0 if fail_count == 0 else 1\n\n\nif __name__ == "__main__":\n\traise SystemExit(main())\n'


_WINDOWS_IMPL = 'from __future__ import annotations\n\nimport os\nimport re\nimport shutil\nimport subprocess\nimport tempfile\nfrom pathlib import Path\n\nfrom _windows_common_ import apply_proxy_env_from_config, load_config, project_root, resolve_path\n\n\ndef is_true(v: object) -> bool:\n    return str(v).strip().lower() in {"1", "true", "yes"}\n\n\ndef venv_python(build_dir: Path) -> Path:\n    venv = build_dir / "openvino.genai" / "tools" / "llm_bench" / "python-env"\n    p = venv / "Scripts" / "python.exe"\n    if p.is_file():\n        return p\n    p2 = venv / "bin" / "python"\n    return p2\n\n\ndef run_capture(cmd: list[str], env: dict[str, str], cwd: Path) -> tuple[int, str]:\n    p = subprocess.run(cmd, cwd=str(cwd), env=env, capture_output=True, text=True)\n    out = (p.stdout or "") + (p.stderr or "")\n    if out:\n        print(out, end="" if out.endswith("\\n") else "\\n")\n    return p.returncode, out\n\n\ndef get_transformers_version(py: Path, env: dict[str, str], cwd: Path) -> str:\n    code = "import transformers; print(transformers.__version__)"\n    p = subprocess.run([str(py), "-c", code], cwd=str(cwd), env=env, capture_output=True, text=True)\n    return (p.stdout or "").strip() if p.returncode == 0 else ""\n\n\ndef install_transformers(py: Path, env: dict[str, str], cwd: Path, version: str) -> bool:\n    if not version:\n        return False\n    cmd = [str(py), "-m", "pip", "install", "-q", f"transformers=={version}"]\n    return subprocess.run(cmd, cwd=str(cwd), env=env).returncode == 0\n\n\ndef uninstall_transformers(py: Path, env: dict[str, str], cwd: Path) -> None:\n    subprocess.run([str(py), "-m", "pip", "uninstall", "-y", "transformers"], cwd=str(cwd), env=env, capture_output=True, text=True)\n\n\ndef extract_failure_reason(output: str) -> str:\n    patterns = [\n        r"Maximum required is.*",\n        r"not supported.*",\n        r"unsupported.*",\n        r"Unknown model type.*",\n        r"requires\\s+transformers.*",\n        r"ValueError.*",\n        r"RuntimeError.*",\n        r"OSError.*",\n        r"Exception.*",\n        r"Traceback.*",\n    ]\n    lines = [ln.strip() for ln in output.splitlines() if ln.strip()]\n    for pat in patterns:\n        m = [ln for ln in lines if re.search(pat, ln, flags=re.IGNORECASE)]\n        if m:\n            return m[-1]\n    return lines[-1] if lines else "Unknown export failure (empty log output)"\n\n\ndef extract_transformers_target_version(output: str) -> str:\n    m = re.search(r"Maximum required is\\s+([0-9]+\\.[0-9]+\\.[0-9]+)", output)\n    if m:\n        return m.group(1)\n    m = re.search(r"requires\\s+transformers[^0-9]*([0-9]+\\.[0-9]+\\.[0-9]+)", output, flags=re.IGNORECASE)\n    if m:\n        return m.group(1)\n    m = re.search(r"transformers==([0-9]+\\.[0-9]+\\.[0-9]+)", output)\n    return m.group(1) if m else ""\n\n\ndef optimum_export_cmd(py: Path, model: str, out_dir: Path, params: dict) -> list[str]:\n    cmd = [\n        str(py),\n        "-m",\n        "optimum.commands.optimum_cli",\n        "export",\n        "openvino",\n        "-m",\n        model,\n    ]\n\n    wf = str(params.get("weight_format", "") or "").strip()\n    if wf:\n        cmd += ["--weight-format", wf]\n\n    if is_true(params.get("sym", False)):\n        cmd += ["--sym"]\n\n    ratio = params.get("ratio")\n    if str(ratio).strip() not in {"", "None"}:\n        cmd += ["--ratio", str(ratio)]\n\n    gs = params.get("group_size")\n    if str(gs).strip() not in {"", "None"}:\n        cmd += ["--group-size", str(gs)]\n\n    if is_true(params.get("trust_remote_code", False)):\n        cmd += ["--trust-remote-code"]\n\n    cmd += [str(out_dir)]\n    return cmd\n\n\ndef export_with_optional_transformers_retry(\n    py: Path,\n    model: str,\n    device: str,\n    hf_root: Path,\n    params: dict,\n    env: dict[str, str],\n    cwd: Path,\n    initial_tf: str,\n) -> tuple[Path | None, str | None]:\n    tmp = Path(tempfile.mkdtemp(prefix=f".{device.lower()}_", dir=str(hf_root)))\n    rc, out = run_capture(optimum_export_cmd(py, model, tmp, params), env, cwd)\n    if rc == 0:\n        return tmp, None\n\n    combined = out\n    target = extract_transformers_target_version(combined)\n    changed_tf = False\n\n    if target:\n        print(f"Info: {device} export for {model} suggests transformers=={target}. Retrying with that version")\n        current = get_transformers_version(py, env, cwd)\n        changed_tf = current != target\n\n        if install_transformers(py, env, cwd, target):\n            shutil.rmtree(tmp, ignore_errors=True)\n            tmp = Path(tempfile.mkdtemp(prefix=f".{device.lower()}_retry_", dir=str(hf_root)))\n            rc2, out2 = run_capture(optimum_export_cmd(py, model, tmp, params), env, cwd)\n            if rc2 == 0:\n                if changed_tf:\n                    if initial_tf:\n                        print(f"Info: Restoring transformers=={initial_tf}")\n                        install_transformers(py, env, cwd, initial_tf)\n                    else:\n                        print("Info: Restoring environment by removing transformers")\n                        uninstall_transformers(py, env, cwd)\n                return tmp, None\n            combined = (combined + "\\n" + out2).strip()\n        else:\n            print(f"Warning: Failed to install transformers=={target} for retry.")\n\n    if changed_tf:\n        if initial_tf:\n            print(f"Info: Restoring transformers=={initial_tf}")\n            install_transformers(py, env, cwd, initial_tf)\n        else:\n            print("Info: Restoring environment by removing transformers")\n            uninstall_transformers(py, env, cwd)\n\n    reason = extract_failure_reason(combined)\n    shutil.rmtree(tmp, ignore_errors=True)\n    return None, reason\n\n\ndef main() -> int:\n    root = project_root(__file__)\n    cfg = load_config(root)\n    env = dict(os.environ)\n    apply_proxy_env_from_config(cfg, env)\n\n    hf_token = str(((cfg.get("ir_models", {}) or {}).get("hf_token", "") or "")).strip()\n    if hf_token:\n        env["HF_TOKEN"] = hf_token\n        env["HUGGINGFACE_HUB_TOKEN"] = hf_token\n        env["HF_HUB_TOKEN"] = hf_token\n        print("Applied optional hf_token from config.yaml")\n\n    build_dir = resolve_path(root, cfg.get("build_dir"), "./BUILD")\n    hf_root = resolve_path(root, cfg.get("ir_dir"), "./MODELS/ir")\n    hf_root.mkdir(parents=True, exist_ok=True)\n    print(f"IR models root set to: {hf_root}")\n\n    py = venv_python(build_dir)\n    if not py.is_file():\n        raise RuntimeError("GenAI Python environment missing. Run genai_build.py first.")\n\n    chk = subprocess.run([str(py), "-m", "optimum.commands.optimum_cli", "--help"], capture_output=True, text=True, env=env)\n    if chk.returncode != 0:\n        raise RuntimeError("optimum-cli not found in GenAI environment")\n\n    ir_models = cfg.get("ir_models", {}) or {}\n    models = [str(m).strip() for m in (ir_models.get("models", []) or []) if str(m).strip()]\n    if not models:\n        raise RuntimeError("No models found in ir_models.models")\n\n    params = ir_models.get("params", {}) or {}\n    gpu_params = params.get("gpu", {}) or {}\n    npu_params = params.get("npu", {}) or {}\n\n    initial_tf = get_transformers_version(py, env, root)\n    if initial_tf:\n        print(f"Detected transformers version: {initial_tf}")\n    else:\n        print("Warning: transformers is not currently installed in the active environment.")\n\n    success_count = 0\n    fail_count = 0\n    failures: list[str] = []\n    status_items: list[str] = []\n\n    for model in models:\n        print("\\n============================================================")\n        print(f"Model: {model}")\n        print("============================================================")\n\n        stripped = model.split("/", 1)[-1]\n        safe_name = stripped.replace("/", "__")\n\n        for device, pset in (("NPU", npu_params), ("GPU", gpu_params)):\n            out_dir = hf_root / device / safe_name\n            if (out_dir / "openvino_model.xml").is_file():\n                print(f"Skipping {device} export for {model} (already exists at {out_dir})")\n                success_count += 1\n                status_items.append(f"{device}|{model}|QUANTIZED")\n                continue\n\n            print(f"Exporting {device} model: {model} -> {out_dir}")\n            tmp, reason = export_with_optional_transformers_retry(py, model, device, hf_root, pset, env, root, initial_tf)\n\n            if tmp and tmp.is_dir():\n                out_dir.parent.mkdir(parents=True, exist_ok=True)\n                shutil.rmtree(out_dir, ignore_errors=True)\n                shutil.move(str(tmp), str(out_dir))\n                success_count += 1\n                status_items.append(f"{device}|{model}|QUANTIZED")\n            else:\n                fail_count += 1\n                msg = reason or "Unknown export failure"\n                print(f"Warning: {device} export failed for {model}")\n                print(f"Reason: {msg}")\n                failures.append(f"{device}|{model}|{msg}")\n                status_items.append(f"{device}|{model}|NOT_QUANTIZED")\n\n    print("\\nDevice-wise quantization status:")\n    if status_items:\n        for item in status_items:\n            d, m, s = item.split("|", 2)\n            print(f"  - {d} :: {m} :: {s}")\n    else:\n        print("  - NONE")\n\n    print("\\nSummary:")\n    print(f"  - successful_exports: {success_count}")\n    print(f"  - failed_exports: {fail_count}")\n\n    if failures:\n        print("\\nFailures:")\n        for item in failures:\n            d, m, r = item.split("|", 2)\n            print(f"  - {d} :: {m} :: {r}")\n\n    print("Process complete.")\n    return 0 if fail_count == 0 else 1\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'


